
// Import vendor modules.
import { access } from "node:fs/promises";
import { basename } from "node:path";
import { join } from "node:path";
import { readFileSync } from "node:fs";
import { Reporter } from "@parcel/plugin";
import { rm } from "node:fs/promises";
import { writeFile } from "node:fs/promises";

// ----------------------------------------------------------------------------------- //
// ----------------------------------------------------------------------------------- //

/**
* I convert the `.html` entry files - generated by the Parcel build - into `.cfm` files
* that can be `cfmodule`d into the ColdFusion application.
*/
export default new Reporter({
	async report({ event, options, logger }) {

		if ( event.type !== "buildSuccess" ) {

			return;

		}

		var config = await getConfig( options );
		var bundleGraph = event.bundleGraph;
		var bundles = bundleGraph.getBundles();
		var template = readFileSync( new URL( "./template.cfm", import.meta.url ), "utf8" );

		for ( var bundle of bundles ) {

			if ( bundle.type !== "html" ) {

				continue;

			}

			var filePath = bundle.filePath;

			// In `parcel watch`, a rebuild only re-emits the `.html` files whose contents
			// have actually changed. However, since Parcel will still iterate over all
			// bundles in the build, we need to skip over any `.html` file that we deleted
			// in a previous build (see down below). Essentially, we're using the `.html`
			// file as a flag even though we never actually consume this file.
			if ( ! ( await fileExists( filePath ) ) ) {

				continue;

			}

			// The nonce attribute and authority (scheme + host) prefix are injected into
			// the markup as CFML expressions that will be evaluated at request time.
			var nonceAttribute = config.nonce.targets.includes( bundle.target.name )
				? `nonce="${ config.nonce.expression }"`
				: ""
			;
			var authority = config.authority.targets.includes( bundle.target.name )
				? config.authority.expression
				: ""
			;

			// In order to have control over the output, we're constructing the asset tags
			// (link and script) directly from the bundle graph rather than reading the
			// `.html` markup that Parcel build emitted.
			var tags = bundleGraph
				.getReferencedBundles( bundle )
				.sort( sortStylesFirst )
				.map(
					( reference ) => {

						var url = `${ authority }${ reference.target.publicUrl }/${ basename( reference.filePath ) }`;

						switch ( reference.type ) {
							case "css":
								return `<link ${ nonceAttribute } rel="stylesheet" href="${ url }" />`;
							break;
							case "js":
								return `<script ${ nonceAttribute } type="module" src="${ url }"></script>`;
							break;
							default:
								throw new Error( `Unexpected bundle type referenced by entry: ${ reference.type }.` );
							break;
						}

					}
				)
				.join( "\n\t" )
			;

			// Inject the asset tags into the CFML module template.
			var cfml = template.replace( "{{ body }}", tags );
			// Parcel generated `.html` files. And while ColdFusion can consume HTML files
			// via CFInclude, it makes more semantic (and security) sense to convert the
			// file to `.cfm`. This way, no information can be leaked by making a direct
			// request to this static asset ingress file.
			var cfmlPath = filePath.replace( /\.html?$/i, ".cfm" );

			await writeFile( cfmlPath, cfml, "utf8" );
			await rm( filePath );
			// Output the prepared file to the docker output. This is for my own benefit
			// as a developer, so that I don't forget this is happening.
			logger.info({
				message: cfmlPath
			});

		}

	}
});

// ----------------------------------------------------------------------------------- //
// ----------------------------------------------------------------------------------- //

/**
* I read the plugin configuration from the project's package.json file.
*/
async function getConfig( options ) {

	var packageJson = JSON.parse(
		await options.inputFS.readFile(
			join( options.projectRoot, "package.json" ),
			"utf8"
		)
	);
	var pluginConfig = ( packageJson[ "parcel-reporter-prepare-cfml" ] || {} );
	var nonceConfig = ( pluginConfig.nonce || {} );
	var authorityConfig = ( pluginConfig.authority || {} );

	return {
		nonce: {
			expression: ( nonceConfig.expression || "" ),
			targets: ( nonceConfig.targets || [] )
		},
		authority: {
			expression: ( authorityConfig.expression || "" ),
			targets: ( authorityConfig.targets || [] )
		}
	};

}


/**
* I determine whether the given file exists. A missing file is an expected condition (in
* `parcel watch`, bundles that didn't change have no `.html` file); any other access error
* is re-thrown.
*/
async function fileExists( filePath ) {

	try {

		await access( filePath );

		return true;

	} catch ( error ) {

		if ( error.code === "ENOENT" ) {

			return false;

		}

		throw error;

	}

}


/**
* I sort bundles such that stylesheets come before scripts. This keeps the styles ahead of
* the script in the rendered document, which mirrors the natural cascade order.
*/
function sortStylesFirst( a, b ) {

	if ( a.type === b.type ) {

		return 0;

	}

	return ( a.type === "css" )
		? -1
		: 1
	;

}
